  stormy:       { gradient:"linear-gradient(135deg, #cbd5e1 0%, #94a3b8 50%, #64748b 100%)", accent:"#1e293b", label:"Stormy",       emoji:"⛈️",  particles:"rain" },
  snowy:        { gradient:"linear-gradient(135deg, #f8fafc 0%, #e2e8f0 50%, #cbd5e1 100%)", accent:"#0ea5e9", label:"Snow",         emoji:"❄️", particles:"snow" },
  fog:          { gradient:"linear-gradient(135deg, #e5e7eb 0%, #d1d5db 50%, #9ca3af 100%)", accent:"#6b7280", label:"Foggy",        emoji:"🌫️", particles:"fog" },
  "clear-night":{ gradient:"linear-gradient(135deg, #1e293b 0%, #334155 50%, #475569 100%)", accent:"#a78bfa", label:"Clear Night",  emoji:"🌙", particles:"stars" },
