/** Read weather prefs from localStorage. Returns a stable shape. */
function _readWeatherPrefs() {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEYS.weatherPrefs) || "null") || {}; }
  catch { return {}; }
}
function _writeWeatherPrefs(p) {
  try { localStorage.setItem(STORAGE_KEYS.weatherPrefs, JSON.stringify(p)); } catch {}
}

/** Hook: returns { enabled, weather, mood, error, toggle, refresh } */
function useWeatherMood() {
  const [prefs, setPrefs] = useState(() => _readWeatherPrefs());
  const [weather, setWeather] = useState(() => _readWeatherPrefs().data || null);
  const [error, setError] = useState("");

  const enabled = !!prefs.enabled;
  const mood = weather ? classifyWeather(weather.temp, weather.code, weather.isDay) : null;

  // Fetch weather for given coords. Returns { temp, code, isDay, locationName }.
  const fetchWeather = async (lat, lng) => {
    try {
      const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}&current=temperature_2m,weather_code,is_day&timezone=auto`;
      const res = await fetch(url);
      if (!res.ok) throw new Error("Weather fetch failed");
      const data = await res.json();
      const c = data.current || {};
      return {
        temp: Number(c.temperature_2m ?? 0),
        code: Number(c.weather_code   ?? 0),
        isDay: Number(c.is_day        ?? 1),
        locationName: "",
        fetchedAt: Date.now(),
      };
    } catch (e) {
      throw e;
    }
  };

  // Try to pull a human-readable city name from coords (BigDataCloud — free)
  const reverseGeocode = async (lat, lng) => {
    try {
      const url = `https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=${lat}&longitude=${lng}&localityLanguage=en`;
      const res = await fetch(url);
      if (!res.ok) return "";
      const d = await res.json();
      return d.city || d.locality || d.principalSubdivision || "";
    } catch { return ""; }
  };

  // Request location + fetch weather + persist
  const enable = async () => {
    setError("");
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      setError("Location is not available on this device.");
      return;
    }
    return new Promise((resolve) => {
      navigator.geolocation.getCurrentPosition(
        async (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          try {
            const w = await fetchWeather(lat, lng);
            const locationName = await reverseGeocode(lat, lng);
            const next = { enabled: true, lat, lng, data: { ...w, locationName }, lastFetch: Date.now() };
            _writeWeatherPrefs(next);
            setPrefs(next);
            setWeather(next.data);
            resolve(true);
          } catch (e) {
            setError("Couldn't fetch weather right now.");
            resolve(false);
          }
        },
        (err) => {
          setError(err.code === 1 ? "Location permission denied." : "Couldn't read location.");
          resolve(false);
        },
        { enableHighAccuracy: false, timeout: 10000, maximumAge: 5 * 60 * 1000 }
      );
    });
  };

  const disable = () => {
    const next = { ..._readWeatherPrefs(), enabled: false };
    _writeWeatherPrefs(next);
    setPrefs(next);
  };

  const toggle = async () => {
    if (enabled) disable();
    else await enable();
  };

  // Auto-refresh every 30 minutes when enabled
  useEffect(() => {
    if (!enabled || !prefs.lat || !prefs.lng) return;
    const tick = async () => {
      try {
        const w = await fetchWeather(prefs.lat, prefs.lng);
        const next = { ...prefs, data: { ...w, locationName: prefs.data?.locationName || "" }, lastFetch: Date.now() };
        _writeWeatherPrefs(next);
        setWeather(next.data);
      } catch {}
    };
    const id = setInterval(tick, _WEATHER_REFRESH_MS);
    // Refresh on enable if last fetch was old
    if (prefs.lastFetch && Date.now() - prefs.lastFetch > _WEATHER_REFRESH_MS) tick();
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, prefs.lat, prefs.lng]);

  return { enabled, weather, mood, error, toggle, refresh: () => prefs.lat && fetchWeather(prefs.lat, prefs.lng).then(setWeather).catch(() => {}) };
}

/* ============================================================
   WEATHER BACKGROUND — themed full-page overlay.

   Renders behind everything else (z-index -1, fixed, pointer-events
   none). The gradient and particle layers respect prefers-reduced-
   motion: animations halt, only the static gradient remains.
   ============================================================ */
function WeatherMoodBackground({ mood }) {
  const reducedMotion = typeof window !== "undefined"
    && window.matchMedia
    && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  if (!mood || !WEATHER_THEMES[mood]) return null;
  const theme = WEATHER_THEMES[mood];

  // Particles — pre-computed positions for each theme
  const renderParticles = () => {
    if (reducedMotion) return null;
    switch (theme.particles) {
      case "rain":
        return (
          <div className="weather-rain">
            {Array.from({ length: 60 }).map((_, i) => (
              <span key={i} style={{
                left: `${(i * 1.7) % 100}%`,
                animationDelay: `${(i * 0.13) % 2}s`,
                animationDuration: `${0.7 + (i % 5) * 0.15}s`,
              }} />
            ))}
          </div>
        );
      case "snow":
        return (
          <div className="weather-snow">
            {Array.from({ length: 40 }).map((_, i) => (
              <span key={i} style={{
                left: `${(i * 2.5) % 100}%`,
                animationDelay: `${(i * 0.4) % 8}s`,
                animationDuration: `${6 + (i % 4) * 1.5}s`,
                fontSize: `${10 + (i % 3) * 4}px`,
              }}>❄</span>
            ))}
          </div>
        );
      case "stars":
        return (
          <div className="weather-stars">
            {Array.from({ length: 50 }).map((_, i) => (
              <span key={i} style={{
                left: `${(i * 2 + (i % 7)) % 100}%`,
                top: `${((i * 5) + (i % 11) * 3) % 90}%`,
                animationDelay: `${(i * 0.2) % 4}s`,
              }} />
            ))}
          </div>
        );
      case "heat":
        return (
          <div className="weather-heat">
            {Array.from({ length: 8 }).map((_, i) => (
              <span key={i} style={{
                left: `${10 + i * 11}%`,
                animationDelay: `${i * 0.4}s`,
                animationDuration: `${4 + (i % 3)}s`,
              }} />
            ))}
          </div>
        );
      case "sun":
        return <div className="weather-sun" />;
      case "frost":
        return (
          <div className="weather-frost">
            {Array.from({ length: 18 }).map((_, i) => (
              <span key={i} style={{
                left: `${(i * 5.7) % 100}%`,
                top: `${(i * 7) % 100}%`,
                animationDelay: `${(i * 0.3) % 5}s`,
              }} />
            ))}
          </div>
        );
      case "breeze":
        return (
          <div className="weather-breeze">
            {Array.from({ length: 6 }).map((_, i) => (
              <span key={i} style={{
                top: `${15 + i * 13}%`,
                animationDelay: `${i * 1.3}s`,
                animationDuration: `${10 + (i % 3) * 2}s`,
              }} />
            ))}
          </div>
        );
      case "fog":
        return <div className="weather-fog" />;
      default:
        return null;
    }
  };

  return (
    <div className="weather-mood-bg" aria-hidden="true">
      <div className="weather-gradient" style={{ background: theme.gradient }} />
      {renderParticles()}
    </div>
  );
}

/* ============================================================
   WEATHER STATUS CHIP — small element shown in TopBar / user menu
   so the user can see the active mood at a glance.
   ============================================================ */
function WeatherStatusChip({ mood, weather, compact = false }) {
  if (!mood || !weather) return null;
  const theme = WEATHER_THEMES[mood];
  if (!theme) return null;
  return (
    <div className="flex items-center gap-1.5 text-[11px] text-[#00304a]" title={`${theme.label} — ${weather.locationName || "Your location"}`}>
      <span style={{ filter:"saturate(1.1)" }}>{theme.emoji}</span>
      {!compact && <span className="font-semibold">{Math.round(weather.temp)}°C</span>}
      {!compact && weather.locationName && <span className="text-slate-500 truncate max-w-[120px]">{weather.locationName}</span>}
    </div>
  );
}


