function roleColorById(id) { return ROLE_COLOR_SWATCHES.find(c => c.id === id) || ROLE_COLOR_SWATCHES[0]; }

/** Default role definitions seeded on first run. The hardcoded
 *  permission sets here mirror the previous if-else `userCan()`
 *  exactly — so existing users with role "admin", "ops", or "finance"
 *  continue to behave identically after migration. */
function defaultRoles() {
  const opsCaps = [
    "book-shipment", "edit-shipment", "change-status", "upload-pod",
    "bulk-status-change", "bulk-export",
    "manage-warehouses", "manage-vehicles", "manage-billing-clients",
    "view-documents", "manage-documents",
    "view-reports", "export-reports", "custom-report-builder",
    "freight-calculator", "ewb-prep", "share-driver-packet", "generate-lr",
  ];
  const financeCaps = [
    ...opsCaps,
    "view-finance", "edit-cost", "edit-revenue",
    "view-vendor-payments", "edit-vendor-payments", "view-tds-report",
    "manage-vendors", "manage-sub-transporters", "delete-shipment",
    "view-deleted", "restore-shipment",
  ];
  // Admin gets everything EXCEPT purge — only super-admin can permanently
  // remove a shipment from the deleted archive. This is the safety net.
  const adminCaps = ALL_CAPS.filter(c => c !== "purge-shipment");
  return [
    { id: "super-admin", label: "Super Admin", color: "lavender", capabilities: ALL_CAPS.slice(), locked: true,  builtin: true,
      description: "Locked role with full access. Cannot be edited or deleted. Use for the system owner / IT lead." },
    { id: "admin",       label: "Admin",       color: "blue",     capabilities: adminCaps,       locked: false, builtin: true,
      description: "Full access by default. An admin can edit this role to remove caps if needed (e.g. lock down user-management)." },
    { id: "finance",     label: "Finance",     color: "lime",     capabilities: financeCaps,     locked: false, builtin: true,
      description: "Finance team — full operational access plus all cost / revenue / vendor-payment capabilities." },
    { id: "ops",         label: "Operations",  color: "mint",     capabilities: opsCaps,         locked: false, builtin: true,
      description: "Operations team — booking, tracking, master data; no finance figures or vendor payments." },
  ];
}

/** Capability check using the data-driven roles array. Lookup is O(role.caps).
 *  Falls back to denying everything if user/role/roles missing. */
function userCan(user, capability, roles) {
  if (!user) return false;
  if (!Array.isArray(roles) || roles.length === 0) return false;

  // ─── COMPANY-WIDE LOCK (v67): shipment deletion is disabled for ───
  // ─── EVERYONE — super-admin, admin, finance, ops, all sub-users. ───
  // Applies to both soft delete and permanent purge. Restore and
  // view-deleted remain available. To ever re-enable, this block must
  // be removed in code — no role configuration can override it.
  if (capability === "delete-shipment" || capability === "purge-shipment") {
    return false;
  }

  // ─── Hardcoded role restrictions (enforced at code level) ───
  // These overrides protect against the role configuration being
  // changed via the Roles editor, an accidental cloud-sync push, or
  // a buggy migration adding capabilities that should never be granted.
  //
  // CURRENT RULE: the "ops" (Operations) role can NEVER delete shipments.
  // The Operations team can book, edit, change status, upload PODs, etc.
  // — but the act of removing a shipment from active records (even as a
  // soft delete) is reserved for Finance, Admin, and Super Admin only.
  // This is a safety guarantee — even if an admin accidentally ticks
  // "Soft-delete shipments" for the Operations role in the Roles editor,
  // the action is still denied here.
  const OPS_FORBIDDEN_CAPS = new Set([
    "delete-shipment",
  ]);
  if (user.role === "ops" && OPS_FORBIDDEN_CAPS.has(capability)) return false;

  const r = roles.find(x => x.id === user.role);
  if (!r) return false;
  return r.capabilities.includes(capability);
}

/** Migrate a role array — adds any new built-in caps that didn't exist
 *  when the role was first seeded (so future patch additions auto-grant
 *  to Admin / Super Admin). Idempotent. */
function migrateRoles(stored) {
  if (!Array.isArray(stored) || stored.length === 0) return defaultRoles();
  const defaults = defaultRoles();
  const out = [];
  for (const def of defaults) {
    const existing = stored.find(r => r.id === def.id);
    if (!existing) { out.push(def); continue; }
    if (def.id === "super-admin") {
      // Always force super-admin to have all caps + locked
      out.push({ ...existing, capabilities: ALL_CAPS.slice(), locked: true, builtin: true });
    } else if (def.id === "admin" && existing.capabilities.length >= ALL_CAPS.length - 5) {
      // Admin had near-full perms — auto-grant any newly added admin-eligible
      // caps so they don't lose tools when the catalog grows. We merge with
      // def.capabilities (the new admin baseline) — NOT ALL_CAPS — so caps
      // explicitly excluded from admin (like purge-shipment) stay excluded
      // even after a role migration.
      const merged = Array.from(new Set([...existing.capabilities, ...def.capabilities]));
      // Remove purge-shipment from admin if it leaked in from a previous version
      const cleaned = merged.filter(c => c !== "purge-shipment");
      out.push({ ...existing, capabilities: cleaned, builtin: true });
    } else {
      out.push({ ...existing, builtin: true });
    }
  }
  // Preserve any custom roles
  for (const r of stored) {
    if (!defaults.some(d => d.id === r.id)) out.push({ ...r, builtin: false });
  }
  return out;
}

/** Hash a PIN with SHA-256 — async. Returns hex string. */
async function hashPin(pin) {
  if (!pin) return "";
  if (typeof crypto !== "undefined" && crypto.subtle) {
    try {
      const enc = new TextEncoder().encode(String(pin));
      const buf = await crypto.subtle.digest("SHA-256", enc);
      return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
    } catch {}
  }
  // Last-resort fallback (should rarely fire) — store as plaintext prefixed
  return "plain:" + String(pin);
}

async function verifyPin(pin, hashed) {
  if (!pin || !hashed) return false;
  if (hashed.startsWith("plain:")) return hashed.slice(6) === String(pin);
  return (await hashPin(pin)) === hashed;
}

/** First-run default Admin: mobile 0000000000, PIN 1234 */
async function defaultBootstrapUsers() {
  const adminPinHash = await hashPin("1234");
  return [{
    id: "u_admin_default",
    name: "Default Admin",
    mobile: "0000000000",
    pinHash: adminPinHash,
    role: "admin",
    active: true,
    createdAt: new Date().toISOString(),
  }];
}

const safeGet = async (key, fallback) => {
  try {
    const r = await window.storage.get(key);
    return r ? JSON.parse(r.value) : fallback;
  } catch { return fallback; }
};
const safeSet = async (key, value) => {
  try {
    await window.storage.set(key, JSON.stringify(value));
    // Pulse the topbar save indicator. Fire-and-forget — no listeners → no-op.
    try { window.dispatchEvent(new CustomEvent("shipzy:save", { detail: { key } })); } catch {}
    // Broadcast the write so CloudSyncEngine can push it to Firestore.
    // The `source: "local"` tag prevents echo-loops with cloud-driven writes
    // (which dispatch source: "cloud" instead — those go the other direction,
    // updating React state via the App-level listener).
    try { window.dispatchEvent(new CustomEvent("shipzy:storage-write", { detail: { key, value, source: "local" } })); } catch {}
  } catch (e) { console.error(e); }
};

/* ============================================================
   CLOUD SYNC — Firebase Firestore (real-time multi-device sync)
   --------------------------------------------------------------
   localStorage is the runtime source of truth on each device. The
   sync engine shadows a fixed set of localStorage keys to Firestore.
   Architecture:
     - safeSet() persists to localStorage AND dispatches a
       "shipzy:storage-write" event with source:"local". The engine
       listens and pushes to Firestore (debounced 600ms).
     - The engine subscribes (onSnapshot) to each Firestore key. When
       another device writes, the engine writes to localStorage and
       dispatches "shipzy:storage-write" with source:"cloud". An
       App-level listener picks that up and updates React state for
       the affected slice, so the UI re-renders without a page reload.
     - Opt-in: if cloud sync is disabled, the engine is a no-op.
       localStorage continues to work normally.

   This is phase 1 — text data only. File blobs (POD/EWB PDFs, vendor
   GST/PAN docs) live in IndexedDB and are NOT synced. Phase 2 with
   Firebase Storage can be added later if needed.
   ============================================================ */

/* Default config baked in for the shipzycart-ftl Firebase project.
   apiKey is NOT a secret — it identifies the project, not authorizes
   access. Real security comes from Firestore rules + Anonymous Auth. */
const DEFAULT_FIREBASE_CONFIG = {
  apiKey:            "AIzaSyBxhJBrqPdVdDTyrCDRJ-tYCx9fD_fWj_A",
  authDomain:        "shipzycart-ftl.firebaseapp.com",
  projectId:         "shipzycart-ftl",
  storageBucket:     "shipzycart-ftl.firebasestorage.app",
  messagingSenderId: "399396335814",
  appId:             "1:399396335814:web:e5e6c7bdbeb8dd178867c7",
  measurementId:     "G-YXZWDKYKVQ",
};

/* Keys we mirror to Firestore. Excluded:
   - session: per-browser login state, never sync
   - weatherPrefs: per-user UI preference, never sync
   - documents: filed under documents-repository TEXT records sync,
     but the underlying file blobs in IndexedDB don't — see phase 2
   - aiConfig: SYNCS in this build (v31+) — small trusted team, opted in.
     Contains the API key. SECURITY NOTE: anyone with workspace access
     and a Firestore-data viewer can read this key. Keep team small,
     rotate the key if anyone leaves, monitor provider billing. */
const SYNCED_STORAGE_KEYS = [
  STORAGE_KEYS.warehouses,
  STORAGE_KEYS.vehicles,
  STORAGE_KEYS.shipments,
  STORAGE_KEYS.billingClients,
  STORAGE_KEYS.vendors,
  STORAGE_KEYS.subTransporters,
  STORAGE_KEYS.documents,
  STORAGE_KEYS.counters,
  STORAGE_KEYS.users,
  STORAGE_KEYS.roles,
  STORAGE_KEYS.aiConfig,
  STORAGE_KEYS.ltlConfig,
];

/* Cloud-sync config storage — separate from synced data.
   IMPORTANT: default is `enabled: true`. The Firebase config is baked
   into this build (DEFAULT_FIREBASE_CONFIG above), so a fresh device
   opening the deployed URL should sync immediately — otherwise it has
   no users in localStorage and the login screen shows an empty team.
   The user can opt-OUT via Settings → Cloud Sync if they want a purely
   local install, but opt-in by default makes the live URL work for new
   devices without any setup. */
const CLOUD_CONFIG_KEY = "shipzy:cloudSync:v1";
const loadCloudConfig = () => {
  try {
    const raw = localStorage.getItem(CLOUD_CONFIG_KEY);
    return raw ? JSON.parse(raw) : { enabled: true, workspaceId: "production", firebaseConfig: null };
  } catch { return { enabled: true, workspaceId: "production", firebaseConfig: null }; }
};
const saveCloudConfig = (cfg) => {
  try { localStorage.setItem(CLOUD_CONFIG_KEY, JSON.stringify(cfg)); } catch {}
};

/* Lazy Firebase app handle — avoid double-init on hot edits / re-mounts. */
function _getFirebaseApp(config) {
  if (!window.firebase) return null;
  try { return window.firebase.app("shipzycart"); }
  catch { return window.firebase.initializeApp(config, "shipzycart"); }
}

/* Firestore document IDs can't contain ':' or '/'. Our STORAGE_KEYS
   look like "shipzy:warehouses:v2" — convert ':' to '_' for the doc id. */
const _keyToDocId = (k) => k.replace(/:/g, "_");

/* ============================================================
   FIREBASE AUTH — email/password sign-in for v2026.05.11-8 (Phase A).

   Uses the same Firebase app handle as cloud sync (_getFirebaseApp).
   The Firebase Auth SDK is already loaded as a compat script alongside
   firebase-firestore-compat.js — we use the namespaced API
   (firebase.auth(app)) so no module imports are needed.

   Functions:
     fbAuth()                            — current auth handle or null
     fbCurrentUser()                     — Firebase Auth user or null
     fbSignInWithEmail(email, password)  — returns user or throws
     fbSignOut()                         — clears the session
     fbSendSetupEmail(email)             — admin-side: create account
                                           with throwaway password, then
                                           email a password-reset link.
                                           If the email already exists,
                                           skip the create and just
                                           re-send the reset email.
     fbOnAuthStateChanged(cb)            — subscribe; returns unsubscribe

   All functions tolerate the Firebase SDK not being loaded (returns null
   or throws "Firebase Auth not ready") so the app degrades safely if
   the CDN is blocked.
   ============================================================ */
function fbAuth() {
  const config = loadCloudConfig()?.firebaseConfig || DEFAULT_FIREBASE_CONFIG;
  if (!window.firebase || !window.firebase.auth) return null;
  const app = _getFirebaseApp(config);
  if (!app) return null;
  return window.firebase.auth(app);
}

function fbCurrentUser() {
  const auth = fbAuth();
  return auth ? auth.currentUser : null;
}

async function fbSignInWithEmail(email, password) {
  const auth = fbAuth();
  if (!auth) throw new Error("Firebase Auth isn't loaded yet — check your internet connection and try again.");
  const cred = await auth.signInWithEmailAndPassword(email.trim().toLowerCase(), password);
  return cred.user;
}

async function fbSignOut() {
  const auth = fbAuth();
  if (!auth) return;
  try { await auth.signOut(); } catch {}
}

async function fbSendSetupEmail(email) {
  const config = loadCloudConfig()?.firebaseConfig || DEFAULT_FIREBASE_CONFIG;
  if (!window.firebase || !window.firebase.auth) {
    throw new Error("Firebase Auth isn't loaded yet — check your internet connection.");
  }
  const trimmed = email.trim().toLowerCase();
  // Generate a throwaway random password (16+ chars). The user will set
  // their own via the password-reset email, so this is never communicated.
  const tmpPw = "Tmp-" + Math.random().toString(36).slice(2, 12) + "-" + Math.random().toString(36).slice(2, 8);

  // CRITICAL: Use a SECONDARY Firebase app instance for createUser.
  // The primary Firebase app holds the admin's auth session — calling
  // `createUserWithEmailAndPassword` on it would auto-sign-in the new
  // user, replacing the admin's session and bouncing them to the login
  // screen. A secondary app has its own isolated auth context, so we can
  // create the new user there without touching the primary session.
  // Each call gets a unique name so we can tear it down cleanly via
  // `.delete()` afterwards — Firebase doesn't allow re-initializing an
  // app with the same name.
  const adminAppName = "admin-action-" + Date.now() + "-" + Math.random().toString(36).slice(2, 8);
  let adminApp = null;
  let accountAlreadyExists = false;
  try {
    adminApp = window.firebase.initializeApp(config, adminAppName);
    const adminAuth = window.firebase.auth(adminApp);
    try {
      await adminAuth.createUserWithEmailAndPassword(trimmed, tmpPw);
    } catch (e) {
      if (e?.code === "auth/email-already-in-use") {
        accountAlreadyExists = true;
      } else {
        throw e;
      }
    }
  } finally {
    // Always tear down the secondary app, even if createUser failed.
    // Otherwise the in-memory app instance leaks and a subsequent click
    // would fail at initializeApp() with a duplicate-name error.
    if (adminApp) {
      try { await adminApp.delete(); } catch {}
    }
  }

  // Send the password-reset email via the primary auth context. This is
  // a public Firebase Auth operation (it's also what "Forgot password?"
  // uses) — it doesn't require the admin to be signed in, but using the
  // primary app keeps the operation associated with the workspace's
  // main config (action URL, sender, email template).
  const primaryAuth = fbAuth();
  if (!primaryAuth) throw new Error("Firebase Auth isn't loaded yet — check your internet connection.");
  await primaryAuth.sendPasswordResetEmail(trimmed);

  return { accountAlreadyExists };
}

function fbOnAuthStateChanged(callback) {
  const auth = fbAuth();
  if (!auth) {
    // Retry on a small delay — SDK might still be loading from the CDN
    let cancelled = false;
    const t = setInterval(() => {
      const a = fbAuth();
      if (a) {
        clearInterval(t);
        if (!cancelled) {
          const unsub = a.onAuthStateChanged(callback);
          // Replace the noop returned to caller
          callback._unsub = unsub;
        }
      }
    }, 250);
    return () => { cancelled = true; clearInterval(t); if (callback._unsub) callback._unsub(); };
  }
  return auth.onAuthStateChanged(callback);
}


/* ============================================================
   FIREBASE STORAGE HELPERS  (Phase 2: document blob storage)
   ============================================================
   Documents (PDFs, images) used to be stored as base64 `dataUrl`
   strings inside the documents array, which then got synced to
   Firestore. This bloated Firestore docs (each ~50-500KB) and
   could hit the 1MB-per-doc Firestore limit on large scans.

   With Storage active, document blobs go to Storage at:
     documents/{workspaceId}/{docId}/{filename}
   and the documents array just holds tiny metadata records with
   `storagePath` + `downloadUrl` instead of `dataUrl`.

   Backward compatibility: existing documents created before this
   change have `dataUrl` only. The display code (DocumentPreview,
   download links) checks `downloadUrl` first, falls back to
   `dataUrl` for legacy records. They keep working — no migration.
   ============================================================ */

// Max upload size: 25 MB. Anything larger fails with a clear message;
// the user shouldn't be uploading 25MB+ scans anyway (a sane EWB PDF
// is well under 1MB). If this ever needs to change, it's one number.
const MAX_DOCUMENT_UPLOAD_BYTES = 25 * 1024 * 1024;

function fbStorage() {
  if (typeof window === "undefined") return null;
  if (!window.firebase || !window.firebase.storage) {
    console.warn("[fb-storage] window.firebase.storage is not available — SDK not loaded");
    return null;
  }
  const cfg = (typeof loadCloudConfig === "function" ? loadCloudConfig() : null) || {};
  const fbCfg = cfg.firebaseConfig || (typeof DEFAULT_FIREBASE_CONFIG !== "undefined" ? DEFAULT_FIREBASE_CONFIG : null);
  if (!fbCfg) {
    console.warn("[fb-storage] No firebaseConfig found");
    return null;
  }
  if (!fbCfg.storageBucket) {
    console.warn("[fb-storage] firebaseConfig is missing storageBucket field");
    return null;
  }
  const app = _getFirebaseApp(fbCfg);
  if (!app) {
    console.warn("[fb-storage] _getFirebaseApp returned null");
    return null;
  }
  try {
    const s = window.firebase.storage(app);
    return s;
  } catch (e) {
    console.warn("[fb-storage] firebase.storage(app) threw:", e && (e.code || e.message), e);
    return null;
  }
}

// Sanitise a filename for Storage paths. Storage allows most chars,
// but spaces and unicode quickly turn into URL-encoding nightmares
// when previewed. Keep ASCII alphanumerics, dot, hyphen, underscore.
function sanitiseFilename(name) {
  const cleaned = String(name || "file")
    .replace(/[^\w.\-]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  return cleaned || "file";
}

// Convert a dataUrl back into a Blob — needed when existing flows
// already captured the file as base64 and now want to upload it.
function dataUrlToBlob(dataUrl) {
  if (!dataUrl || typeof dataUrl !== "string") return null;
  const m = dataUrl.match(/^data:([^;,]+)?(;base64)?,(.*)$/);
  if (!m) return null;
  const mime = m[1] || "application/octet-stream";
  const isBase64 = !!m[2];
  const data = m[3];
  try {
    if (isBase64) {
      const bin = atob(data);
      const arr = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
      return new Blob([arr], { type: mime });
    }
    return new Blob([decodeURIComponent(data)], { type: mime });
  } catch (e) {
    return null;
  }
}

/* ============================================================
   Tiny ZIP-store encoder (no compression — method 0).
   Inputs: an array of { name: string, bytes: Uint8Array }.
   Returns: a Blob the browser can download.

   Why no compression: archive contents are jpegs and PDFs which are
   already compressed — deflate buys ~0-5% and costs a lot of CPU plus
   a CRC32 dependency anyway. Store-only keeps the encoder ~80 lines and
   gives the user a perfectly valid .zip every reader can open.

   Format reference: APPNOTE.TXT 4.3.7 (PKWARE ZIP).
   ============================================================ */
function _crc32Table() {
  if (_crc32Table._t) return _crc32Table._t;
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c >>> 0;
  }
  _crc32Table._t = t;
  return t;
}
function _crc32(bytes) {
  const t = _crc32Table();
  let c = 0xFFFFFFFF;
  for (let i = 0; i < bytes.length; i++) c = t[(c ^ bytes[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
}
function buildZipFromFiles(files) {
  // Write little-endian uint32 / uint16 to a DataView.
  const enc = new TextEncoder();
  const parts  = [];               // list of Uint8Array fragments
  const central = [];              // central directory entries
  let offset = 0;

  for (const f of files) {
    const nameBytes = enc.encode(f.name);
    const data      = f.bytes;
    const crc       = _crc32(data);

    // Local file header (30 bytes + name)
    const lfh = new ArrayBuffer(30);
    const lv  = new DataView(lfh);
    lv.setUint32(0,  0x04034b50, true); // signature
    lv.setUint16(4,  20,         true); // version needed
    lv.setUint16(6,  0,          true); // general purpose flag
    lv.setUint16(8,  0,          true); // compression method = 0 (store)
    lv.setUint16(10, 0,          true); // mod time
    lv.setUint16(12, 0x21,       true); // mod date — arbitrary; date headers don't matter for our use
    lv.setUint32(14, crc,        true);
    lv.setUint32(18, data.length, true); // compressed size = same (no compression)
    lv.setUint32(22, data.length, true); // uncompressed size
    lv.setUint16(26, nameBytes.length, true);
    lv.setUint16(28, 0,          true); // extra field length

    parts.push(new Uint8Array(lfh));
    parts.push(nameBytes);
    parts.push(data);

    // Central directory header (46 bytes + name) — built now, written later
    const cdh = new ArrayBuffer(46);
    const cv  = new DataView(cdh);
    cv.setUint32(0,  0x02014b50, true);
    cv.setUint16(4,  20,         true); // version made by
    cv.setUint16(6,  20,         true); // version needed
    cv.setUint16(8,  0,          true);
    cv.setUint16(10, 0,          true);
    cv.setUint16(12, 0,          true);
    cv.setUint16(14, 0x21,       true);
    cv.setUint32(16, crc,        true);
    cv.setUint32(20, data.length, true);
    cv.setUint32(24, data.length, true);
    cv.setUint16(28, nameBytes.length, true);
    cv.setUint16(30, 0,          true);
    cv.setUint16(32, 0,          true);
    cv.setUint16(34, 0,          true);
    cv.setUint16(36, 0,          true);
    cv.setUint32(38, 0,          true);
    cv.setUint32(42, offset,     true);

    central.push(new Uint8Array(cdh));
    central.push(nameBytes);

    offset += 30 + nameBytes.length + data.length;
  }

  const cdStart = offset;
  let cdSize = 0;
  for (const p of central) {
    parts.push(p);
    cdSize += p.length;
  }

  // End of central directory record (22 bytes)
  const eocd = new ArrayBuffer(22);
  const ev   = new DataView(eocd);
  ev.setUint32(0,  0x06054b50, true);
  ev.setUint16(4,  0,          true);
  ev.setUint16(6,  0,          true);
  ev.setUint16(8,  files.length, true);
  ev.setUint16(10, files.length, true);
  ev.setUint32(12, cdSize,     true);
  ev.setUint32(16, cdStart,    true);
  ev.setUint16(20, 0,          true);
  parts.push(new Uint8Array(eocd));

  return new Blob(parts, { type: "application/zip" });
}

/* Helper: trigger a browser download of a Blob. Wrapped so callers
   don't need to wire up object URLs each time. */
function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  // Free the URL after a tick to let the browser process the click.
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/* Build a ZIP from a list of doc records (each with a dataUrl).
   File-name collisions are auto-suffixed (-2, -3, ...) so two docs
   with the same fileName don't overwrite each other in the ZIP. */
async function buildDocsZip(docs) {
  const seen = new Map(); // name → count
  const files = [];
  for (const d of docs) {
    if (!d.dataUrl) continue;
    const blob = dataUrlToBlob(d.dataUrl);
    if (!blob) continue;
    const ab = await blob.arrayBuffer();
    let name = d.fileName || `${d.id || "doc"}.bin`;
    const used = seen.get(name) || 0;
    if (used > 0) {
      // foo.pdf → foo-2.pdf
      const dot = name.lastIndexOf(".");
      name = dot > 0
        ? name.slice(0, dot) + `-${used + 1}` + name.slice(dot)
        : `${name}-${used + 1}`;
    }
    seen.set(d.fileName || name, used + 1);
    files.push({ name, bytes: new Uint8Array(ab) });
  }
  return buildZipFromFiles(files);
}


// Upload a Blob/File to Firebase Storage. Returns:
//   { storagePath, downloadUrl, size, mimeType }  on success
//   { failed: true, reason: "..." }               on failure
//
// The CALLER decides what to do on failure. Per user preference,
// the document-upload flows fall back to saving as a dataUrl so the
// document isn't lost — slower sync but more resilient.
async function fbUploadDocumentBlob({ blob, docId, filename, workspaceId, onProgress }) {
  const _log = (...args) => console.log("[fb-storage]", `doc=${docId}`, ...args);
  _log("start — fbUploadDocumentBlob called");

  const storage = fbStorage();
  if (!storage) {
    _log("FAIL — fbStorage() returned null (SDK not loaded or no Firebase app)");
    return { failed: true, reason: "Firebase Storage SDK not loaded" };
  }
  _log("got storage handle. bucket =", (storage.app && storage.app.options && storage.app.options.storageBucket) || "(unknown)");

  if (!blob) {
    _log("FAIL — no blob");
    return { failed: true, reason: "No file to upload" };
  }
  _log("blob size =", blob.size, "type =", blob.type);

  if (blob.size > MAX_DOCUMENT_UPLOAD_BYTES) {
    const mb = (blob.size / 1024 / 1024).toFixed(1);
    _log("FAIL — over limit:", mb, "MB");
    return { failed: true, reason: `File is ${mb} MB — max upload size is 25 MB. Try compressing or splitting the file.` };
  }

  const ws = sanitiseFilename(workspaceId || "default");
  const safeName = sanitiseFilename(filename || "file");
  const path = `documents/${ws}/${docId}/${safeName}`;
  _log("upload path =", path);

  // RECOVERY PATH: if a file already exists at this path (e.g. uploaded by
  // a previous session that failed to record the downloadUrl back to the
  // doc record before the cloud-sync race overwrote local state), just
  // fetch the existing URL and short-circuit. Saves bandwidth, sidesteps
  // any overwrite-permission edge cases, and self-heals doc records that
  // lost their URL fields between sessions.
  try {
    const ref = storage.ref(path);
    const existingUrl = await ref.getDownloadURL();
    if (existingUrl) {
      _log("file already exists — recovered downloadUrl, skipping upload");
      // We don't know the exact size of the existing blob without an extra
      // metadata fetch; the doc's existing size field will be preserved by
      // the caller's `result.size || d.size` merge. Mark this clearly so the
      // caller can log differently if it wants.
      return {
        storagePath: path,
        downloadUrl: existingUrl,
        size: blob.size,                  // assume current blob matches
        mimeType: blob.type || "application/octet-stream",
        recovered: true,
      };
    }
  } catch (e) {
    // getDownloadURL throws if the object doesn't exist — that's the
    // expected case for a fresh upload, so we just proceed below.
    if (e && e.code !== "storage/object-not-found") {
      _log("getDownloadURL precheck threw (non-not-found):", e.code || e.message);
    }
  }

  // Make sure we have a fresh auth token before attempting the upload.
  // The Storage SDK reads the token from the app's auth integration; if
  // we just signed in, the token may not have propagated to the storage
  // request yet. Forcing a refresh removes that race.
  try {
    const auth = window.firebase.auth(storage.app);
    if (auth && auth.currentUser) {
      await auth.currentUser.getIdToken(/* forceRefresh */ true);
      _log("auth token refreshed");
    } else {
      _log("WARN — no auth.currentUser at upload time; request will be anonymous");
    }
  } catch (e) {
    _log("token refresh threw:", e && (e.code || e.message));
  }

  try {
    const ref = storage.ref(path);
    _log("got ref, starting put()…");
    const task = ref.put(blob, { contentType: blob.type || "application/octet-stream" });
    if (typeof onProgress === "function") {
      task.on("state_changed", (snap) => {
        const pct = snap.totalBytes > 0 ? (snap.bytesTransferred / snap.totalBytes) : 0;
        try { onProgress(pct); } catch {}
      });
    }
    // Surface upload errors via the task's state_changed channel too —
    // sometimes the awaited task swallows errors that the listener catches.
    task.on(
      "state_changed",
      (snap) => {
        _log("progress", Math.round(((snap.bytesTransferred || 0) / (snap.totalBytes || 1)) * 100) + "%");
      },
      (err) => {
        _log("STATE_CHANGED ERROR:", err && (err.code || err.message), err);
      },
      () => {
        _log("task completed (state_changed final callback)");
      }
    );
    await task;
    _log("await task resolved");
    const downloadUrl = await ref.getDownloadURL();
    _log("SUCCESS — got downloadUrl");
    return {
      storagePath: path,
      downloadUrl,
      size: blob.size,
      mimeType: blob.type || "application/octet-stream",
    };
  } catch (e) {
    console.warn("[fb-storage]", `doc=${docId}`, "CAUGHT exception:", e && (e.code || e.message), e);

    // FALLBACK PATH: if the Firebase SDK's put() failed with auth-related
    // 403, try a manual fetch upload with an explicit Authorization header.
    // The SDK's compat auth-integration sometimes fails to attach the
    // token even though auth.currentUser is valid — directly constructing
    // the upload request with the bearer token bypasses that layer.
    const code = (e && e.code) || "";
    if (code === "storage/unauthorized") {
      try {
        const _logF = (...args) => console.log("[fb-storage]", `doc=${docId}`, "[fetch-fallback]", ...args);
        _logF("trying manual fetch upload with explicit auth header");

        const auth = window.firebase.auth(storage.app);
        if (!auth || !auth.currentUser) throw new Error("no currentUser for fetch fallback");
        const token = await auth.currentUser.getIdToken(false);
        const bucket = storage.app.options.storageBucket;
        const safePath = encodeURIComponent(path);
        const url = `https://firebasestorage.googleapis.com/v0/b/${bucket}/o?name=${safePath}`;
        _logF("POST to", url);

        const resp = await fetch(url, {
          method: "POST",
          headers: {
            "Authorization": `Firebase ${token}`,
            "Content-Type":  blob.type || "application/octet-stream",
          },
          body: blob,
        });
        _logF("response status =", resp.status);
        if (!resp.ok) {
          const body = await resp.text().catch(() => "(no body)");
          _logF("response body =", body.slice(0, 500));
          throw new Error(`fetch upload failed: HTTP ${resp.status}`);
        }
        const meta = await resp.json();
        // Firebase Storage returns a downloadTokens field; construct the public URL.
        const downloadToken = (meta.downloadTokens || "").split(",")[0];
        if (!downloadToken) throw new Error("upload succeeded but no downloadToken in response");
        const downloadUrl = `https://firebasestorage.googleapis.com/v0/b/${bucket}/o/${safePath}?alt=media&token=${downloadToken}`;
        _logF("SUCCESS via fetch fallback");
        return {
          storagePath: path,
          downloadUrl,
          size: blob.size,
          mimeType: blob.type || "application/octet-stream",
          viaFetchFallback: true,
        };
      } catch (e2) {
        console.warn("[fb-storage]", `doc=${docId}`, "[fetch-fallback] FAILED:", e2 && (e2.code || e2.message));
        return {
          failed: true,
          reason: `${e.code || e.message} (fetch fallback also failed: ${e2.message})`,
        };
      }
    }

    return {
      failed: true,
      reason: (e && (e.code || e.message)) || "Storage upload failed",
    };
  }
}

// Best-effort blob removal on hard delete. Failures are logged
// silently — orphaned blobs are not catastrophic and cleaning them
// up periodically via a console script is cheap.
async function fbDeleteDocumentBlob(storagePath) {
  if (!storagePath) return;
  const storage = fbStorage();
  if (!storage) return;
  try {
    await storage.ref(storagePath).delete();
  } catch (e) {
    console.warn("[fb-storage] Failed to delete blob:", storagePath, e && (e.code || e.message));
  }
}

// Resolve a document's display URL. New uploads have downloadUrl,
// legacy ones have dataUrl. This is the single source of truth used
// by DocumentPreview and download buttons.
function documentDisplayUrl(doc) {
  if (!doc) return null;
  return doc.downloadUrl || doc.dataUrl || null;
}

/* ============================================================
   AI INTEGRATION

   Provider-agnostic layer for calling third-party LLM APIs from the
   browser. Supports OpenAI, Anthropic Claude, and Google Gemini.

   Storage: the API key + provider + model preference live ONLY in
   localStorage (STORAGE_KEYS.aiConfig). Deliberately excluded from
   cloud sync because the API key is sensitive — if it were synced
   to Firestore, anyone with workspace access could read it.

   The callAI() function takes a normalised messages-array shape
   (same as Anthropic / OpenAI Chat Completions) and translates to
   whatever the chosen provider expects. Callers don't need to know
   provider-specific details.
   ============================================================ */

const AI_PROVIDERS = {
  openai: {
    label: "OpenAI",
    endpoint: "https://api.openai.com/v1/chat/completions",
    apiKeyHint: "starts with 'sk-...'",
    apiKeyPattern: /^sk-/,
    suggestedModels: [
      "gpt-4o", "gpt-4o-mini", "gpt-4-turbo", "gpt-3.5-turbo",
    ],
    defaultModel: "gpt-4o-mini",
  },
  anthropic: {
    label: "Anthropic Claude",
    endpoint: "https://api.anthropic.com/v1/messages",
    apiKeyHint: "starts with 'sk-ant-...'",
    apiKeyPattern: /^sk-ant-/,
    suggestedModels: [
      "claude-opus-4-5", "claude-sonnet-4-5", "claude-haiku-4-5",
    ],
    defaultModel: "claude-haiku-4-5",
  },
  google: {
    label: "Google Gemini",
    endpoint: "https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent",
    apiKeyHint: "from Google AI Studio",
    apiKeyPattern: /^[A-Za-z0-9_-]{20,}$/,
    suggestedModels: [
      "gemini-2.5-pro", "gemini-2.5-flash", "gemini-2.5-flash-lite",
    ],
    defaultModel: "gemini-2.5-flash",
  },
  openrouter: {
    label: "OpenRouter",
    endpoint: "https://openrouter.ai/api/v1/chat/completions",
    apiKeyHint: "starts with 'sk-or-v1-...'",
    apiKeyPattern: /^sk-or-/,
    // OpenRouter exposes hundreds of models from many providers behind one
    // API key. Models are namespaced as `provider/model-name`. We list a
    // sensible mix of paid, recent, and free options — user can type any
    // OpenRouter-supported model in the free-text input.
    suggestedModels: [
      "anthropic/claude-sonnet-4.5",
      "anthropic/claude-haiku-4.5",
      "openai/gpt-4o",
      "openai/gpt-4o-mini",
      "google/gemini-2.5-flash",
      "deepseek/deepseek-chat",
      "meta-llama/llama-3.3-70b-instruct:free",
      "google/gemini-2.0-flash-exp:free",
    ],
    defaultModel: "google/gemini-2.5-flash",
  },
};

function loadAIConfig() {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.aiConfig);
    if (!raw) return null;
    let parsed = JSON.parse(raw);
    // Legacy compatibility: v31–v40 mistakenly dispatched the storage-write
    // event with an already-stringified value, so the cloud reconciler
    // double-encoded any config written on Device A when Device B (or the
    // same device after a hard-refresh) pulled it back down. If we detect
    // that shape — a string that parses to another JSON object — unwrap it
    // and rewrite localStorage in the correct single-encoded form so the
    // next reload is clean.
    if (typeof parsed === "string") {
      try {
        const inner = JSON.parse(parsed);
        if (inner && typeof inner === "object") {
          parsed = inner;
          localStorage.setItem(STORAGE_KEYS.aiConfig, JSON.stringify(inner));
        }
      } catch {}
    }
    return (parsed && typeof parsed === "object") ? parsed : null;
  } catch {
    return null;
  }
}

function saveAIConfig(cfg) {
  try {
    const json = JSON.stringify(cfg);
    localStorage.setItem(STORAGE_KEYS.aiConfig, json);
    // Dispatch the RAW OBJECT (not the JSON string) so the CloudSyncEngine
    // stringifies it exactly once when pushing to Firestore. Passing the
    // pre-stringified `json` here caused a double-encode bug (v31-v40) that
    // made the API key look "disappear" on hard-refresh.
    try {
      window.dispatchEvent(new CustomEvent("shipzy:storage-write", {
        detail: { key: STORAGE_KEYS.aiConfig, value: cfg, source: "local" }
      }));
    } catch {}
    return true;
  } catch {
    return false;
  }
}

function clearAIConfig() {
  try {
    localStorage.removeItem(STORAGE_KEYS.aiConfig);
    // Dispatch with empty value so cloud sync also removes the Firestore
    // entry (otherwise next reload would pull the cloud copy back).
    try {
      window.dispatchEvent(new CustomEvent("shipzy:storage-write", {
        detail: { key: STORAGE_KEYS.aiConfig, value: null, source: "local" }
      }));
    } catch {}
  } catch {}
}

function isAIConfigured() {
  const c = loadAIConfig();
  return !!(c && c.provider && c.apiKey && c.model);
}

/* ============================================================
   LTL API CONFIG + CLIENT
   Talks to the ShipzyCart CRM Integration API described in
   README.md. Config contains { apiKey, baseUrl }. Base URL is
   the Firebase Cloud Functions v2 root (e.g.
   https://asia-south1-shipzy-vendor.cloudfunctions.net), and
   each endpoint is a distinct function under that root.
   ============================================================ */
function loadLtlConfig() {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.ltlConfig);
    if (!raw) return null;
    let parsed = JSON.parse(raw);
    // Self-heal any legacy double-encoded value (same defensive
    // logic loadAIConfig applies — a string that parses to an object
    // means the CloudSyncEngine wrote a stringified value).
    if (typeof parsed === "string") {
      try {
        const inner = JSON.parse(parsed);
        if (inner && typeof inner === "object") {
          parsed = inner;
          localStorage.setItem(STORAGE_KEYS.ltlConfig, JSON.stringify(inner));
        }
      } catch {}
    }
    return (parsed && typeof parsed === "object") ? parsed : null;
  } catch { return null; }
}

function saveLtlConfig(cfg) {
  try {
    localStorage.setItem(STORAGE_KEYS.ltlConfig, JSON.stringify(cfg));
    // Dispatch the RAW OBJECT (not the JSON string) so the CloudSyncEngine
    // stringifies it exactly once when pushing to Firestore.
    try {
      window.dispatchEvent(new CustomEvent("shipzy:storage-write", {
        detail: { key: STORAGE_KEYS.ltlConfig, value: cfg, source: "local" }
      }));
    } catch {}
    return true;
  } catch { return false; }
}

function clearLtlConfig() {
  try {
    localStorage.removeItem(STORAGE_KEYS.ltlConfig);
    try {
      window.dispatchEvent(new CustomEvent("shipzy:storage-write", {
        detail: { key: STORAGE_KEYS.ltlConfig, value: null, source: "local" }
      }));
    } catch {}
  } catch {}
}

function isLtlConfigured() {
  const c = loadLtlConfig();
  return !!(c && c.apiKey && c.baseUrl);
}

/* Call the LTL API. `endpoint` is the path segment (e.g. "/apiCustomers");
   `opts.method` defaults to GET; `opts.body` is stringified when set;
   `opts.query` becomes URL-encoded query params. Throws on non-2xx or
   missing config; returns the parsed JSON body on success. */

/* ── Backend base for OUR functions (EWB, share, inbox, integrations) ──
   Primary home: the shipzycart-ftl project itself (post-Blaze). During
   migration — or if a call ever fails there — we transparently retry on
   the configured LTL base (shipzy-vendor), where the same functions were
   historically deployed. Same X-Shipzy-API-Key on both. ── */
const FTL_API_BASE = "https://us-central1-shipzycart-ftl.cloudfunctions.net";

async function callFtlApi(endpoint, opts = {}) {
  const cfg = loadLtlConfig();
  if (!cfg || !cfg.apiKey) throw new Error("API not configured — open Settings → LTL Rates API");
  const path = endpoint.startsWith("/") ? endpoint : "/" + endpoint;
  const doFetch = async (base) => {
    let url = base.replace(/\/+$/, "") + path;
    if (opts.query) {
      const qs = new URLSearchParams();
      for (const [k, v] of Object.entries(opts.query)) if (v != null && v !== "") qs.append(k, String(v));
      const qStr = qs.toString();
      if (qStr) url += (url.includes("?") ? "&" : "?") + qStr;
    }
    const res = await fetch(url, {
      method: opts.method || "GET",
      headers: {
        "X-Shipzy-API-Key": cfg.apiKey,
        "Content-Type": "application/json",
        "Accept": "application/json",
      },
      body: opts.body ? JSON.stringify(opts.body) : undefined,
    });
    let data = null;
    try { data = await res.json(); } catch {}
    return { res, data };
  };
  let out;
  try {
    out = await doFetch(FTL_API_BASE);
    // 404 = function not deployed on the new home yet → fall back
    if (out.res.status === 404 && cfg.baseUrl) out = await doFetch(cfg.baseUrl);
  } catch (e) {
    // network-level failure on the new home → fall back
    if (cfg.baseUrl) out = await doFetch(cfg.baseUrl);
    else throw e;
  }
  const { res, data } = out;
  if (!res.ok) {
    const msg = (data && (data.message || data.error)) || res.statusText || `HTTP ${res.status}`;
    throw new Error(`${res.status} — ${msg}`);
  }
  if (data && data.ok === false) throw new Error(data.message || data.error || "API returned ok=false");
  return data;
}

async function callLtlApi(endpoint, opts = {}) {
  const cfg = loadLtlConfig();
  if (!cfg || !cfg.apiKey || !cfg.baseUrl) throw new Error("LTL API not configured — open Settings → LTL Rates API");
  const base = cfg.baseUrl.replace(/\/+$/, "");
  const path = endpoint.startsWith("/") ? endpoint : "/" + endpoint;
  let url = base + path;
  if (opts.query) {
    const qs = new URLSearchParams();
    for (const [k, v] of Object.entries(opts.query)) if (v != null && v !== "") qs.append(k, String(v));
    const qStr = qs.toString();
    if (qStr) url += (url.includes("?") ? "&" : "?") + qStr;
  }
  const res = await fetch(url, {
    method: opts.method || "GET",
    headers: {
      "X-Shipzy-API-Key": cfg.apiKey,
      "Content-Type": "application/json",
      "Accept": "application/json",
    },
    body: opts.body ? JSON.stringify(opts.body) : undefined,
  });
  let data = null;
  try { data = await res.json(); } catch {}
  if (!res.ok) {
    const msg = (data && (data.message || data.error)) || res.statusText || `HTTP ${res.status}`;
    throw new Error(`${res.status} — ${msg}`);
  }
  if (data && data.ok === false) {
    throw new Error(data.message || data.error || "API returned ok=false");
  }
  return data;
}

/* Call the configured AI provider with a chat-completions-style request.
   Returns the assistant's reply text on success.
   Throws Error on failure (no AI configured, network error, API error).

   Parameters:
     - messages: array of { role: "user" | "assistant", content: "..." }
     - system: optional string with system instructions
     - maxTokens: optional cap on output length (default 1024)
     - temperature: optional creativity (default 0.7)
*/
async function callAI({ messages, system, maxTokens = 1024, temperature = 0.7 } = {}) {
  const cfg = loadAIConfig();
  if (!cfg || !cfg.provider || !cfg.apiKey || !cfg.model) {
    throw new Error("AI not configured. Open Settings → AI Assistant and add your API key.");
  }
  if (!Array.isArray(messages) || messages.length === 0) {
    throw new Error("callAI: messages array is required and must be non-empty");
  }

  const prov = AI_PROVIDERS[cfg.provider];
  if (!prov) throw new Error(`Unknown AI provider: ${cfg.provider}`);

  // Track usage in a simple counter so the user can see what they're spending.
  const trackUsage = () => {
    try {
      const today = new Date().toISOString().slice(0, 10);
      const usage = JSON.parse(localStorage.getItem("shipzy:aiUsage:v1") || "{}");
      usage[today] = (usage[today] || 0) + 1;
      // Keep only last 60 days to avoid bloat
      const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - 60);
      const cutoffISO = cutoff.toISOString().slice(0, 10);
      for (const d in usage) if (d < cutoffISO) delete usage[d];
      localStorage.setItem("shipzy:aiUsage:v1", JSON.stringify(usage));
    } catch {}
  };

  if (cfg.provider === "openai" || cfg.provider === "openrouter") {
    // OpenRouter speaks the OpenAI Chat Completions wire format, so the
    // request body is identical. The only differences are the endpoint
    // URL and two optional headers OpenRouter uses for analytics (we
    // include them to identify ourselves nicely in OpenRouter dashboards).
    const body = {
      model: cfg.model,
      messages: system ? [{ role: "system", content: system }, ...messages] : messages,
      max_tokens: maxTokens,
      temperature,
    };
    const headers = {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${cfg.apiKey}`,
    };
    if (cfg.provider === "openrouter") {
      // These headers are optional but recommended by OpenRouter — they
      // help identify the app in OpenRouter's traffic dashboards and don't
      // change billing or behaviour. Both are safe to send in browser.
      headers["HTTP-Referer"] = "https://shipzycart-ftl.web.app";
      headers["X-Title"]      = "ShipzyCart FTL";
    }
    const resp = await fetch(prov.endpoint, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
    });
    if (!resp.ok) {
      const err = await resp.text().catch(() => "");
      throw new Error(`${prov.label} ${resp.status}: ${err.slice(0, 300)}`);
    }
    const data = await resp.json();
    trackUsage();
    return data.choices?.[0]?.message?.content || "";
  }

  if (cfg.provider === "anthropic") {
    const body = {
      model: cfg.model,
      max_tokens: maxTokens,
      temperature,
      messages,
    };
    if (system) body.system = system;
    const resp = await fetch(prov.endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": cfg.apiKey,
        "anthropic-version": "2023-06-01",
        // The DANGEROUS-direct-browser-access flag is required by Anthropic
        // to acknowledge the user knows their key is exposed to the browser.
        // It's their explicit safety opt-in, not actually risky in itself.
        "anthropic-dangerous-direct-browser-access": "true",
      },
      body: JSON.stringify(body),
    });
    if (!resp.ok) {
      const err = await resp.text().catch(() => "");
      throw new Error(`Anthropic ${resp.status}: ${err.slice(0, 300)}`);
    }
    const data = await resp.json();
    trackUsage();
    // Response is { content: [{ type: "text", text: "..." }, ...] }
    return (data.content || [])
      .filter(b => b.type === "text")
      .map(b => b.text)
      .join("");
  }

  if (cfg.provider === "google") {
    // Gemini expects a different message shape and the model in the URL.
    const url = prov.endpoint.replace("{model}", encodeURIComponent(cfg.model)) +
                `?key=${encodeURIComponent(cfg.apiKey)}`;
    const contents = messages.map(m => ({
      role: m.role === "assistant" ? "model" : "user",
      parts: [{ text: m.content }],
    }));
    const body = {
      contents,
      generationConfig: { maxOutputTokens: maxTokens, temperature },
    };
    if (system) body.systemInstruction = { parts: [{ text: system }] };
    const resp = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!resp.ok) {
      const err = await resp.text().catch(() => "");
      throw new Error(`Gemini ${resp.status}: ${err.slice(0, 300)}`);
    }
    const data = await resp.json();
    trackUsage();
    return data.candidates?.[0]?.content?.parts?.map(p => p.text).join("") || "";
  }

  throw new Error(`Provider not implemented: ${cfg.provider}`);
}

function CloudSyncEngine({ cloudConfig, onStatus }) {
  const fbAppRef     = useRef(null);
  const fsRef        = useRef(null);
  const unsubsRef    = useRef([]);
  const lastPushedRef = useRef({}); // key → JSON-stringified value, debounce + echo-guard
  const pushTimersRef = useRef({}); // key → setTimeout id

  useEffect(() => {
    // Tear down listeners + timers from previous config
    unsubsRef.current.forEach(u => { try { u(); } catch {} });
    unsubsRef.current = [];
    Object.values(pushTimersRef.current).forEach(t => clearTimeout(t));
    pushTimersRef.current = {};

    if (!cloudConfig || !cloudConfig.enabled) {
      onStatus({ state: "idle", message: "Cloud sync disabled" });
      return;
    }
    const cfg = cloudConfig.firebaseConfig || DEFAULT_FIREBASE_CONFIG;
    const workspaceId = cloudConfig.workspaceId || "production";
    if (!cfg.apiKey || !cfg.projectId) {
      onStatus({ state: "error", message: "Missing Firebase config" });
      return;
    }
    if (!window.firebase || !window.firebase.firestore) {
      onStatus({ state: "error", message: "Firebase SDK not loaded — refresh the page" });
      return;
    }

    let cancelled = false;

    const app = _getFirebaseApp(cfg);
    if (!app) { onStatus({ state: "error", message: "Could not initialize Firebase" }); return; }
    fbAppRef.current = app;
    const fs = window.firebase.firestore(app);
    fsRef.current = fs;
    const auth = window.firebase.auth(app);

    const stateCol = fs.collection("workspaces").doc(workspaceId).collection("state");

    // Pending local writes that arrived before auth was ready. Once auth
    // lands and the engine starts, we flush these to Firestore. Map so the
    // latest value per key wins (older queued values are overwritten).
    const pendingPushes = new Map();

    // Engine running flag. True between the auth-ready handler firing and
    // either the user signing out or cleanup. Guards onLocalWrite from
    // pushing while the streams aren't authenticated.
    let started = false;
    let authUnsub = null;

    const startEngine = async () => {
      if (started || cancelled) return;
      started = true;
      onStatus({ state: "connecting", message: "Connecting to cloud\u2026" });

      let setupErrors = 0;
      // Initial reconcile per key. Cloud wins if it has a doc; otherwise
      // local seeds the cloud. Errors don't stop the loop — partial sync
      // is better than nothing.
      for (const key of SYNCED_STORAGE_KEYS) {
        if (cancelled || !started) return;
        try {
          const docRef = stateCol.doc(_keyToDocId(key));
          const snap = await docRef.get();
          if (snap.exists) {
            const data = snap.data();
            if (data && "value" in data) {
              let val = data.value;
              // ── Legacy double-encoding self-heal (aiConfig only) ──
              // Pre-v41, saveAIConfig dispatched an already-stringified
              // value which the engine then stringified again, so any
              // Firestore aiConfig doc written by v31-v40 has value as
              // a JSON string of the config instead of the config object
              // itself. Detect that shape and re-push the clean object.
              if (key === STORAGE_KEYS.aiConfig && typeof val === "string") {
                try {
                  const inner = JSON.parse(val);
                  if (inner && typeof inner === "object") {
                    val = inner;
                    docRef.set({ value: inner, updatedAt: Date.now() }).catch(() => {});
                  }
                } catch {}
              }
              const serialized = JSON.stringify(val);
              const local = await window.storage.get(key);
              if (!local || local.value !== serialized) {
                await window.storage.set(key, serialized);
                window.dispatchEvent(new CustomEvent("shipzy:storage-write", {
                  detail: { key, value: val, source: "cloud" }
                }));
              }
              lastPushedRef.current[key] = serialized;
            }
          } else {
            const local = await window.storage.get(key);
            if (local && local.value) {
              try {
                const parsed = JSON.parse(local.value);
                await docRef.set({ value: parsed, updatedAt: Date.now() });
                lastPushedRef.current[key] = local.value;
              } catch {}
            }
          }
        } catch (err) {
          setupErrors++;
          console.warn("[cloud] reconcile failed for", key, err && (err.code || err.message));
          if (err && (err.code === "permission-denied" || /permission/i.test(err.message || ""))) {
            onStatus({
              state: "error",
              message: "Permission denied. Check Firestore rules — they should allow authenticated users.",
            });
            return;
          }
        }
      }

      if (cancelled || !started) return;
      if (setupErrors === 0) {
        onStatus({ state: "synced", message: "Synced just now", lastSyncAt: Date.now() });
      } else {
        onStatus({
          state: "error",
          message: "Partial sync: " + setupErrors + " key(s) failed. Check console.",
        });
      }

      // Real-time subscriptions — apply remote changes to local
      SYNCED_STORAGE_KEYS.forEach(key => {
        const unsub = stateCol.doc(_keyToDocId(key)).onSnapshot(snap => {
          if (!snap.exists) return;
          const data = snap.data();
          if (!data || !("value" in data)) return;
          const serialized = JSON.stringify(data.value);
          if (lastPushedRef.current[key] === serialized) return;
          lastPushedRef.current[key] = serialized;
          window.storage.set(key, serialized);
          window.dispatchEvent(new CustomEvent("shipzy:storage-write", {
            detail: { key, value: data.value, source: "cloud" }
          }));
          onStatus({ state: "synced", message: "Updated from cloud", lastSyncAt: Date.now() });
        }, err => {
          console.warn("[cloud] snapshot error for", key, err && (err.code || err.message));
          let friendly = "Sync error: " + (err.code || err.message);
          if (err && err.code === "permission-denied") {
            friendly = "Permission denied. Check Firestore rules.";
          }
          onStatus({ state: "error", message: friendly });
        });
        unsubsRef.current.push(unsub);
      });

      // Flush any writes that landed before auth was ready.
      if (pendingPushes.size > 0) {
        console.log("[cloud] flushing", pendingPushes.size, "queued write(s) post-auth");
        for (const [, evt] of pendingPushes) {
          window.dispatchEvent(new CustomEvent("shipzy:storage-write", { detail: evt }));
        }
        pendingPushes.clear();
      }
    };

    const stopEngine = () => {
      unsubsRef.current.forEach(u => { try { u(); } catch {} });
      unsubsRef.current = [];
      Object.values(pushTimersRef.current).forEach(t => clearTimeout(t));
      pushTimersRef.current = {};
      started = false;
    };

    // Push local changes to Firestore, debounced 600ms per key. When auth
    // isn't ready yet, queue the latest value per key in pendingPushes
    // (overwriting older queued values for the same key) — startEngine
    // flushes the queue after the auth-gated setup completes.
    const onLocalWrite = (e) => {
      const d = e.detail || {};
      if (!SYNCED_STORAGE_KEYS.includes(d.key)) return;
      if (d.source !== "local") return;
      if (!started) {
        pendingPushes.set(d.key, d);
        return;
      }
      const fsNow = fsRef.current;
      if (!fsNow) return;
      const serialized = JSON.stringify(d.value);
      if (lastPushedRef.current[d.key] === serialized) return;

      clearTimeout(pushTimersRef.current[d.key]);
      pushTimersRef.current[d.key] = setTimeout(() => {
        const docRef = fsNow.collection("workspaces").doc(workspaceId).collection("state").doc(_keyToDocId(d.key));
        docRef.set({ value: d.value, updatedAt: Date.now() }).then(() => {
          lastPushedRef.current[d.key] = serialized;
          onStatus({ state: "synced", message: "Synced just now", lastSyncAt: Date.now() });
        }).catch(err => {
          console.warn("[cloud] push failed for", d.key, err && (err.code || err.message));
          let friendly = "Push failed: " + (err.code || err.message);
          if (err && err.code === "permission-denied") {
            friendly = "Push denied. Check Firestore rules.";
          }
          onStatus({ state: "error", message: friendly });
        });
      }, 600);
    };
    window.addEventListener("shipzy:storage-write", onLocalWrite);

    // Gate the engine on Firebase Auth state. Without this, the reconcile
    // loop fires before the user has signed in — Firestore rejects every
    // request because the auth header is empty, and the SDK's internal
    // write-stream handshake throws an Uncaught Promise rejection that
    // can't be caught from userland code. By waiting for onAuthStateChanged
    // to deliver a real user we ensure every Firestore RPC carries a valid
    // token from the first byte.
    onStatus({ state: "connecting", message: "Waiting for sign-in\u2026" });
    authUnsub = auth.onAuthStateChanged(user => {
      if (cancelled) return;
      if (user) {
        startEngine();
      } else {
        stopEngine();
        onStatus({ state: "idle", message: "Sign in to start cloud sync" });
      }
    });

    return () => {
      cancelled = true;
      if (authUnsub) try { authUnsub(); } catch {}
      stopEngine();
      window.removeEventListener("shipzy:storage-write", onLocalWrite);
    };
  }, [JSON.stringify(cloudConfig)]);

  return null;
}


/* ============================================================
   PRESENCE ENGINE — who's online right now

   Each browser writes a heartbeat document to:
     workspaces/{workspaceId}/presence/{userId}
   every 30 seconds. The doc contains the user's name, role, and
   `lastSeen` timestamp.

   A user is considered "online" if their lastSeen is within the
   last 60 seconds (i.e. they've sent a heartbeat in roughly the
   last cycle).

   When the browser closes (visibilitychange → hidden, beforeunload),
   we attempt one final write marking them offline so the UI doesn't
   need to wait the full 60s timeout.

   Multi-tab dedup: keyed by userId, so 3 tabs of the same user
   appear as 1 person online.

   Cost: ~2 writes/min/user. For a 5-person team active 8h/day,
   ~5 × 8 × 60 × 2 = 4,800 writes/day. Free tier is 20K/day.
   ============================================================ */

const PRESENCE_HEARTBEAT_MS  = 30_000;  // write every 30s
const PRESENCE_ONLINE_WINDOW = 60_000;  // online if seen within 60s

function PresenceEngine({ cloudConfig, currentUser, onPresenceUpdate }) {
  const heartbeatTimerRef = useRef(null);
  const unsubRef          = useRef(null);

  useEffect(() => {
    if (heartbeatTimerRef.current) { clearInterval(heartbeatTimerRef.current); heartbeatTimerRef.current = null; }
    if (unsubRef.current) { try { unsubRef.current(); } catch {} unsubRef.current = null; }

    if (!cloudConfig || !cloudConfig.enabled) { onPresenceUpdate([]); return; }
    if (!currentUser) return;
    if (!window.firebase || !window.firebase.firestore) return;

    const cfg = cloudConfig.firebaseConfig || DEFAULT_FIREBASE_CONFIG;
    const workspaceId = cloudConfig.workspaceId || "production";
    const app = _getFirebaseApp(cfg);
    if (!app) return;
    const fs = window.firebase.firestore(app);
    const presenceCol = fs.collection("workspaces").doc(workspaceId).collection("presence");
    const myRef = presenceCol.doc(currentUser.id);

    let cancelled = false;

    // Write heartbeat — best-effort, swallows errors
    const beat = async (online = true) => {
      if (cancelled) return;
      try {
        await myRef.set({
          userId:   currentUser.id,
          name:     currentUser.name || "User",
          role:     currentUser.role || "ops",
          mobile:   currentUser.mobile || "",
          lastSeen: Date.now(),
          online,
        });
      } catch (e) {
        // Permission or network — silently ignore. Presence is best-effort.
      }
    };

    // Initial heartbeat + interval
    beat(true);
    heartbeatTimerRef.current = setInterval(() => beat(true), PRESENCE_HEARTBEAT_MS);

    // Subscribe to ALL presence docs in this workspace
    unsubRef.current = presenceCol.onSnapshot(snap => {
      const now = Date.now();
      const list = [];
      snap.forEach(doc => {
        const d = doc.data();
        if (!d || !d.userId) return;
        const lastSeen = Number(d.lastSeen || 0);
        const online = d.online !== false && (now - lastSeen) < PRESENCE_ONLINE_WINDOW;
        list.push({
          userId:  d.userId,
          name:    d.name || "User",
          role:    d.role || "ops",
          mobile:  d.mobile || "",
          lastSeen,
          online,
        });
      });
      // Sort: online first (by name), then offline (by most-recent first)
      list.sort((a, b) => {
        if (a.online !== b.online) return a.online ? -1 : 1;
        if (a.online) return a.name.localeCompare(b.name);
        return b.lastSeen - a.lastSeen;
      });
      onPresenceUpdate(list);
    }, err => {
      // Ignore — presence isn't critical
    });

    // Mark offline before unload — best-effort, browser may not run async
    const onUnload = () => { try { myRef.set({ online: false, lastSeen: Date.now() }, { merge: true }); } catch {} };
    const onVisChange = () => {
      if (document.visibilityState === "hidden") {
        try { myRef.set({ online: false, lastSeen: Date.now() }, { merge: true }); } catch {}
      } else {
        beat(true); // returned to tab — heartbeat immediately
      }
    };
    window.addEventListener("beforeunload", onUnload);
    document.addEventListener("visibilitychange", onVisChange);

    return () => {
      cancelled = true;
      clearInterval(heartbeatTimerRef.current);
      heartbeatTimerRef.current = null;
      if (unsubRef.current) { try { unsubRef.current(); } catch {} unsubRef.current = null; }
      window.removeEventListener("beforeunload", onUnload);
      document.removeEventListener("visibilitychange", onVisChange);
      // Best-effort: mark offline on unmount
      try { myRef.set({ online: false, lastSeen: Date.now() }, { merge: true }); } catch {}
    };
  }, [JSON.stringify(cloudConfig), currentUser?.id]);

  return null;
}


