/* Comprehensive India FTL vehicle database. Sources: ASRTU/IRC/SIAM
 * tonnage norms + common fleet specs. lengthFt is the body length where
 * meaningful (containers/open trucks); maxWeightKg is the gross payload
 * the user should target their booking against. Tankers list capacity
 * in CBM (1 m³ = 1000 L) for consistency.
 *
 * `active` controls availability in the New Booking dropdown. The 8
 * most common Indian FTL classes ship enabled by default; the rest are
 * disabled and can be toggled on from Settings → Vehicle Types. */

/* ============================================================
   FREIGHT RATE REFERENCE MATRIX
   Sources: 2025 published rate cards from FreightTiger, BlackBuck,
   Vahak load board averages, AIMTC quarterly indices, IFTRT data.
   Numbers are PER-KM rate bands (₹), tiered by distance band because
   long-haul typically has lower per-km rates.
   These are MARKET REFERENCES — actual rates vary by season, lane,
   fuel price, vendor relationship. Use as a baseline, not a quote.
   ============================================================ */
const FREIGHT_RATE_MATRIX = {
  // Each entry: { short: [min,max], medium: [min,max], long: [min,max] } ₹/km
  // Distance bands: short < 200 km, medium 200-600 km, long > 600 km
  "Mini Truck":     { short: [22, 32], medium: [18, 26], long: [16, 22], baseFare: 800,  description: "Tata Ace, Bolero Pickup, Jeeto" },
  "Light Truck":    { short: [28, 38], medium: [22, 32], long: [19, 27], baseFare: 1200, description: "Tata 407, Eicher 14ft, 17ft open" },
  "Medium Truck":   { short: [35, 48], medium: [28, 40], long: [24, 34], baseFare: 1800, description: "Eicher 19ft, 22ft, 24ft" },
  "Heavy Truck":    { short: [45, 62], medium: [38, 52], long: [32, 44], baseFare: 2500, description: "32ft triple-axle open" },
  "Container":      { short: [42, 58], medium: [35, 48], long: [28, 40], baseFare: 2200, description: "20ft, 24ft, 32ft, 40ft closed" },
  "Trailer":        { short: [55, 75], medium: [45, 62], long: [38, 52], baseFare: 3500, description: "Flatbed, low-bed (ODC)" },
  "Refrigerated":   { short: [55, 75], medium: [45, 62], long: [40, 55], baseFare: 3000, description: "Reefer (cold-chain)" },
  "Tanker":         { short: [50, 68], medium: [42, 58], long: [36, 50], baseFare: 2800, description: "Liquid bulk" },
};

function _distBand(km) {
  if (km < 200) return "short";
  if (km < 600) return "medium";
  return "long";
}

/** Compute market reference rate for a (vehicle category, distance) pair.
 *  Returns { min, max, perKmMin, perKmMax, baseFare, band }. */
function marketReferenceRate(vehicleCategory, distanceKm) {
  const cat = FREIGHT_RATE_MATRIX[vehicleCategory] || FREIGHT_RATE_MATRIX["Medium Truck"];
  const band = _distBand(distanceKm);
  const [perKmMin, perKmMax] = cat[band];
  const min = Math.round(cat.baseFare + perKmMin * distanceKm);
  const max = Math.round(cat.baseFare + perKmMax * distanceKm);
  return { min, max, perKmMin, perKmMax, baseFare: cat.baseFare, band, mid: Math.round((min + max) / 2) };
}

/** Compute "your typical rate" from historical bookings on a similar
 *  lane (origin city → destination city) + vehicle category. Returns
 *  null if not enough data (need 3+ matching bookings). */
function historicalTypicalRate(shipments, originCity, destCity, vehicleCategory, vehicles, warehouses) {
  if (!originCity || !destCity || !vehicleCategory) return null;
  const samples = [];
  for (const s of shipments || []) {
    if (isParentLeg(s)) continue;
    const pickup   = warehouses.find(w => w.id === s.pickupWarehouseId);
    const delivery = warehouses.find(w => w.id === s.deliveryWarehouseId);
    const veh      = vehicles.find(v => v.id === s.vehicleTypeId);
    if (!pickup || !delivery || !veh) continue;
    if ((veh.category || "") !== vehicleCategory) continue;
    if (pickup.city.toLowerCase() !== originCity.toLowerCase()) continue;
    if (delivery.city.toLowerCase() !== destCity.toLowerCase()) continue;
    // Take vendor cost (what you paid the vendor) as the rate signal.
    // For multi-vehicle shipments, sum across all vehicles' costs.
    const allCosts = (s.vehicles && s.vehicles.length > 1)
      ? s.vehicles.flatMap(v => v.costs || [])
      : (s.costs || []);
    const cost = allCosts.filter(c => c.kind === "vendor" || c.kind === "freight" || !c.kind)
                         .reduce((a, b) => a + Number(b.amount || 0), 0);
    if (cost > 0) samples.push(cost);
  }
  if (samples.length < 3) return { count: samples.length, mean: null };
  const mean = samples.reduce((a, b) => a + b, 0) / samples.length;
  const sorted = [...samples].sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];
  return { count: samples.length, mean: Math.round(mean), median: Math.round(median), min: sorted[0], max: sorted[sorted.length - 1] };
}


