/* Migrate previously-stored vehicles. Idempotent — safe to call on
 * every load:
 *   - existing entries get active=true (preserve their behaviour)
 *   - any seed entry not in storage is appended (with its seed default)
 *   - missing category gets back-filled from the seed lookup */
const _SEED_VEHICLES_BY_ID = Object.fromEntries(SEED_VEHICLES.map(v => [v.id, v]));
function migrateVehicles(stored) {
  if (!Array.isArray(stored) || stored.length === 0) return SEED_VEHICLES;
  const existingIds = new Set(stored.map(v => v.id));
  const upgraded = stored.map(v => ({
    ...v,
    active:   v.active !== undefined ? v.active : true,
    category: v.category || _SEED_VEHICLES_BY_ID[v.id]?.category || "Other",
  }));
  const newOnes = SEED_VEHICLES.filter(v => !existingIds.has(v.id));
  return [...upgraded, ...newOnes];
}



