/* ============================================================
   UTILITIES
   ============================================================ */
const fmtINR = (n) => "₹" + Number(n || 0).toLocaleString("en-IN", { maximumFractionDigits: 0 });
const fmtDate = (d) => {
  if (!d) return "—";
  try {
    return new Date(d).toLocaleDateString("en-IN", { day:"2-digit", month:"short", year:"numeric" });
  } catch { return d; }
};
const todayISO = () => new Date().toISOString().slice(0,10);

/* ============================================================
   AUDIT TRAIL — per-shipment event log.

   Each shipment has an `audit: AuditEvent[]` array. Events are
   appended chronologically and never mutated. We store the user's
   name + mobile inline so the trail still reads correctly even if
   the user is later renamed or deleted.

   Why per-shipment instead of a flat audit table?
   localStorage caps at ~5-10MB. A flat audit table grows unbounded
   (50 shipments/day × 8 events/each × 365 = 146k events/year ≈ 30MB).
   Embedding inside each shipment matches the only query we need
   ("look up shipment, see its history") and naturally garbage-
   collects when a shipment is deleted. Trade-off: cross-shipment
   queries ("what did user X do today") aren't supported, but they
   weren't required.

   Tampering note: this is a good-faith log, NOT tamper-proof. With
   browser dev tools any user could edit localStorage. For legally
   defensible audit logs, a backend would be required. Adequate for
   day-to-day operational accountability.
   ============================================================ */
function auditEvent(user, action, details) {
  return {
    ts: Date.now(),
    userId:     user?.id     || "system",
    userName:   user?.name   || "System",
    userMobile: user?.mobile || "",
    action,
    details: details || {},
  };
}

/** Append one event to a shipment's audit array (immutable). */
function appendAudit(shipment, event) {
  return { ...shipment, audit: [...(shipment.audit || []), event] };
}

/** Convenience: append + return updated shipment. */
function logAudit(shipment, user, action, details) {
  return appendAudit(shipment, auditEvent(user, action, details));
}

/** Given the previous + next shipment objects, compute a list of
 *  per-field audit events. Skips internal/computed fields like
 *  `audit`, `_*`, and runtime-only ones. Granularity (a): one event
 *  per changed field — readable, narrow scope, good for "who changed
 *  the vehicle number" queries. */
const _AUDIT_TRACKED_FIELDS = {
  status:              "Status",
  vehicleNumber:       "Vehicle Number",
  driverName:          "Driver Name",
  driverNumber:        "Driver Phone",
  pickupWarehouseId:   "Pickup Warehouse",
  deliveryWarehouseId: "Delivery Warehouse",
  vehicleTypeId:       "Vehicle Type",
  billingClientId:     "Billing Client",
  billingClientPocId:  "Billing POC",
  vendorId:            "Vendor",
  invoiceNo:           "Invoice No.",
  invoiceValue:        "Invoice Value",
  ewayBillNo:          "E-Way Bill No.",
  saidToContain:       "Goods Description",
  remarks:             "Remarks",
  boxes:               "Boxes",
  cbm:                 "CBM",
  weightKg:            "Weight (kg)",
  lrNumber:            "LR Number",
  lrDate:              "LR Date",
  pickupDate:          "Pickup Date",
};

function diffShipmentEvents(prev, next, user) {
  const events = [];
  if (!prev || !next) return events;

  // Top-level scalar changes
  for (const [field, label] of Object.entries(_AUDIT_TRACKED_FIELDS)) {
    const a = prev[field];
    const b = next[field];
    if ((a ?? "") === (b ?? "")) continue;
    // For the status field, use a distinct "status-change" action so
    // it's filterable and visually distinct in the timeline.
    const action = field === "status" ? "status-change" : "field-edit";
    events.push(auditEvent(user, action, { field, label, from: a ?? "", to: b ?? "" }));
  }

  // Cost rows — track add/remove/edit
  const aCosts = prev.costs || [];
  const bCosts = next.costs || [];
  const aCostIds = new Set(aCosts.map(c => c.id));
  const bCostIds = new Set(bCosts.map(c => c.id));
  bCosts.forEach(c => {
    if (!aCostIds.has(c.id)) {
      events.push(auditEvent(user, "cost-add", { name: c.name, amount: c.amount }));
    } else {
      const before = aCosts.find(x => x.id === c.id);
      if (before && (before.name !== c.name || Number(before.amount) !== Number(c.amount))) {
        events.push(auditEvent(user, "cost-edit", {
          name: c.name, fromAmount: before.amount, toAmount: c.amount,
        }));
      }
    }
  });
  aCosts.forEach(c => {
    if (!bCostIds.has(c.id)) {
      events.push(auditEvent(user, "cost-remove", { name: c.name, amount: c.amount }));
    }
  });

  // Revenue rows — same pattern
  const aRev = prev.revenues || [];
  const bRev = next.revenues || [];
  const aRevIds = new Set(aRev.map(r => r.id));
  const bRevIds = new Set(bRev.map(r => r.id));
  bRev.forEach(r => {
    if (!aRevIds.has(r.id)) {
      events.push(auditEvent(user, "revenue-add", { name: r.name, amount: r.amount }));
    } else {
      const before = aRev.find(x => x.id === r.id);
      if (before && (before.name !== r.name || Number(before.amount) !== Number(r.amount))) {
        events.push(auditEvent(user, "revenue-edit", {
          name: r.name, fromAmount: before.amount, toAmount: r.amount,
        }));
      }
    }
  });
  aRev.forEach(r => {
    if (!bRevIds.has(r.id)) {
      events.push(auditEvent(user, "revenue-remove", { name: r.name, amount: r.amount }));
    }
  });

  // Document uploads
  const aDocs = prev.docs || [];
  const bDocs = next.docs || [];
  if (bDocs.length > aDocs.length) {
    const newOnes = bDocs.slice(aDocs.length);
    newOnes.forEach(d => {
      events.push(auditEvent(user, "doc-upload", {
        category: d.category || "Document",
        fileName: d.name || d.fileName || "—",
      }));
    });
  }

  return events;
}

/** Apply a list of audit events to a shipment. Returns the updated
 *  shipment with events appended. Preserves event timestamps. */
function applyAuditEvents(shipment, events) {
  if (!events || events.length === 0) return shipment;
  return { ...shipment, audit: [...(shipment.audit || []), ...events] };
}

/** Diff + apply in one call. Used by save handlers. */
function shipmentWithDiff(prev, next, user) {
  const events = diffShipmentEvents(prev, next, user);
  return applyAuditEvents(next, events);
}

/** Human label + colour for an audit action. */
function auditActionMeta(action) {
  switch (action) {
    case "create":         return { label: "Created",        colour: "#0074ff", bg: "#e6f1ff" };
    case "field-edit":     return { label: "Edited",         colour: "#6366f1", bg: "#eef2ff" };
    case "status-change":  return { label: "Status Change",  colour: "#0a7a64", bg: "#d1fae5" };
    case "cost-add":       return { label: "Cost Added",     colour: "#dc2626", bg: "#fef2f2" };
    case "cost-edit":      return { label: "Cost Edited",    colour: "#dc2626", bg: "#fef2f2" };
    case "cost-remove":    return { label: "Cost Removed",   colour: "#dc2626", bg: "#fef2f2" };
    case "revenue-add":    return { label: "Revenue Added",  colour: "#059669", bg: "#d1fae5" };
    case "revenue-edit":   return { label: "Revenue Edited", colour: "#059669", bg: "#d1fae5" };
    case "revenue-remove": return { label: "Revenue Removed",colour: "#059669", bg: "#d1fae5" };
    case "doc-upload":     return { label: "Doc Uploaded",   colour: "#7c3aed", bg: "#f5f3ff" };
    case "delete":         return { label: "Deleted",        colour: "#991b1b", bg: "#fee2e2" };
    default:               return { label: action || "Event",colour: "#475569", bg: "#f1f5f9" };
  }
}


